// Phase 6 Stage 3: 고급 함수 & 통계 (Advanced Functions & Statistics) 테스트
// Advanced Math, Statistics, Random Functions Testing

use fv_lang::stdlib::advanced;
use fv_lang::Value;

// ============= 통계 함수 테스트 =============

#[test]
fn test_variance_basic() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let var = advanced::variance(&arr).unwrap();
    assert!((var - 0.666666).abs() < 0.01);
}

#[test]
fn test_variance_constant() {
    // 모든 값이 같으면 분산은 0
    let arr = vec![Value::Integer(5), Value::Integer(5), Value::Integer(5)];
    let var = advanced::variance(&arr).unwrap();

