// IR (Intermediate Representation) 정의
// Phase 4: 코드 생성

use crate::types::Type;
use std::fmt;

/// IR 노드는 AST를 더 낮은 수준의 표현으로 변환합니다
#[derive(Debug, Clone, PartialEq)]
pub enum IRNode {
    // === 리터럴 값 ===
    IntLiteral(i64),
    FloatLiteral(f64),
    StringLiteral(String),
    BoolLiteral(bool),

    // === 변수 ===
    Variable(String),

    // === 연산 ===
    BinaryOp {
        op: String,
        left: Box<IRNode>,
        right: Box<IRNode>,
    },
    UnaryOp {
        op: String,
        operand: Box<IRNode>,
    },

    // === 제어 흐름 ===
    If {
        condition: Box<IRNode>,
        then_block: Vec<IRNode>,
        else_block: Option<Vec<IRNode>>,
    },

    // === 함수 ===
    FunctionCall {
        name: String,
        args: Vec<IRNode>,
    },

    // === 배열/튜플 ===
    Array {
        elements: Vec<IRNode>,
    },
    Index {
        expr: Box<IRNode>,
        index: Box<IRNode>,
    },
    Tuple {
        elements: Vec<IRNode>,
    },

    // === 변수 할당 ===
    Assign {
        name: String,
        value: Box<IRNode>,
    },

    // === 반환 ===
    Return(Box<IRNode>),

    // === 다중 명령 ===
    Block(Vec<IRNode>),
}

/// IR 함수 정의
#[derive(Debug, Clone)]
pub struct IRFunction {
    pub name: String,
    pub params: Vec<(String, Type)>,
    pub return_type: Type,
    pub body: Vec<IRNode>,
}

/// IR 프로그램 (함수들의 모음)
#[derive(Debug, Clone)]
pub struct IRProgram {
    pub functions: Vec<IRFunction>,
    pub main: Vec<IRNode>,
}

impl IRNode {
    /// 이 IR 노드가 값을 반환하는지 확인합니다
    pub fn returns_value(&self) -> bool {
        match self {
            IRNode::IntLiteral(_)
            | IRNode::FloatLiteral(_)
            | IRNode::StringLiteral(_)
            | IRNode::BoolLiteral(_)
            | IRNode::Variable(_)
            | IRNode::BinaryOp { .. }
            | IRNode::UnaryOp { .. }
            | IRNode::FunctionCall { .. }
            | IRNode::Array { .. }
            | IRNode::Index { .. }
            | IRNode::Tuple { .. } => true,

            IRNode::If { .. } | IRNode::Assign { .. } | IRNode::Return(_) | IRNode::Block(_) => {
                false
            }
        }
    }

    /// 상수 폴딩: 컴파일 타임에 계산 가능한 상수 값들을 미리 계산합니다
    pub fn fold_constants(&self) -> IRNode {
        match self {
            IRNode::BinaryOp { op, left, right } => {
                let left_folded = left.fold_constants();
                let right_folded = right.fold_constants();

                // 두 피연산자가 모두 상수인 경우 계산
                match (&left_folded, &right_folded) {
                    (IRNode::IntLiteral(l), IRNode::IntLiteral(r)) => {
                        match op.as_str() {
                            "Plus" => IRNode::IntLiteral(l + r),
                            "Minus" => IRNode::IntLiteral(l - r),
                            "Star" => IRNode::IntLiteral(l * r),
                            "Slash" if *r != 0 => IRNode::IntLiteral(l / r),
                            "Percent" if *r != 0 => IRNode::IntLiteral(l % r),
                            _ => IRNode::BinaryOp {
                                op: op.clone(),
                                left: Box::new(left_folded),
                                right: Box::new(right_folded),
                            },
                        }
                    }
                    (IRNode::FloatLiteral(l), IRNode::FloatLiteral(r)) => {
                        match op.as_str() {
                            "Plus" => IRNode::FloatLiteral(l + r),
                            "Minus" => IRNode::FloatLiteral(l - r),
                            "Star" => IRNode::FloatLiteral(l * r),
                            "Slash" => IRNode::FloatLiteral(l / r),
                            _ => IRNode::BinaryOp {
                                op: op.clone(),
                                left: Box::new(left_folded),
                                right: Box::new(right_folded),
                            },
                        }
                    }
                    _ => IRNode::BinaryOp {
                        op: op.clone(),
                        left: Box::new(left_folded),
                        right: Box::new(right_folded),
                    },
                }
            }
            IRNode::UnaryOp { op, operand } => {
                let operand_folded = operand.fold_constants();
                match (&operand_folded, op.as_str()) {
                    (IRNode::IntLiteral(n), "Minus") => IRNode::IntLiteral(-n),
                    (IRNode::FloatLiteral(n), "Minus") => IRNode::FloatLiteral(-n),
                    (IRNode::BoolLiteral(b), "Not") => IRNode::BoolLiteral(!b),
                    _ => IRNode::UnaryOp {
                        op: op.clone(),
                        operand: Box::new(operand_folded),
                    },
                }
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                let condition_folded = condition.fold_constants();

                // 조건이 상수인 경우 불필요한 분기 제거
                match condition_folded {
                    IRNode::BoolLiteral(true) => {
                        let then_folded: Vec<_> =
                            then_block.iter().map(|n| n.fold_constants()).collect();
                        if then_folded.len() == 1 {
                            then_folded[0].clone()
                        } else {
                            IRNode::Block(then_folded)
                        }
                    }
                    IRNode::BoolLiteral(false) => {
                        if let Some(else_stmts) = else_block {
                            let else_folded: Vec<_> =
                                else_stmts.iter().map(|n| n.fold_constants()).collect();
                            if else_folded.len() == 1 {
                                else_folded[0].clone()
                            } else {
                                IRNode::Block(else_folded)
                            }
                        } else {
                            IRNode::Block(vec![])
                        }
                    }
                    _ => IRNode::If {
                        condition: Box::new(condition_folded),
                        then_block: then_block.iter().map(|n| n.fold_constants()).collect(),
                        else_block: else_block
                            .as_ref()
                            .map(|stmts| stmts.iter().map(|n| n.fold_constants()).collect()),
                    },
                }
            }
            IRNode::Block(nodes) => {
                let folded: Vec<_> = nodes.iter().map(|n| n.fold_constants()).collect();
                IRNode::Block(folded)
            }
            _ => self.clone(),
        }
    }

    /// 불필요한 변수 할당을 제거합니다
    pub fn eliminate_dead_code(&self) -> IRNode {
        match self {
            IRNode::Block(nodes) => {
                let mut live_nodes = Vec::new();

                for (i, node) in nodes.iter().enumerate() {
                    match node {
                        IRNode::Assign { name, value } => {
                            // 다음 사용 위치를 찾습니다
                            let is_used = nodes[i + 1..].iter().any(|n| {
                                Self::uses_variable(n, name)
                            });

                            if is_used {
                                live_nodes.push(node.eliminate_dead_code());
                            }
                            // 그렇지 않으면 제거합니다
                        }
                        _ => {
                            live_nodes.push(node.eliminate_dead_code());
                        }
                    }
                }

                IRNode::Block(live_nodes)
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => IRNode::If {
                condition: Box::new(condition.eliminate_dead_code()),
                then_block: then_block.iter().map(|n| n.eliminate_dead_code()).collect(),
                else_block: else_block
                    .as_ref()
                    .map(|stmts| stmts.iter().map(|n| n.eliminate_dead_code()).collect()),
            },
            _ => self.clone(),
        }
    }

    /// 주어진 변수가 이 노드에서 사용되는지 확인합니다
    fn uses_variable(node: &IRNode, name: &str) -> bool {
        match node {
            IRNode::Variable(n) => n == name,
            IRNode::BinaryOp { left, right, .. } => {
                Self::uses_variable(left, name) || Self::uses_variable(right, name)
            }
            IRNode::UnaryOp { operand, .. } => Self::uses_variable(operand, name),
            IRNode::Index { expr, index } => {
                Self::uses_variable(expr, name) || Self::uses_variable(index, name)
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                Self::uses_variable(condition, name)
                    || then_block.iter().any(|n| Self::uses_variable(n, name))
                    || else_block
                        .as_ref()
                        .map_or(false, |stmts| stmts.iter().any(|n| Self::uses_variable(n, name)))
            }
            IRNode::FunctionCall { args, .. } => {
                args.iter().any(|arg| Self::uses_variable(arg, name))
            }
            IRNode::Array { elements } => elements.iter().any(|e| Self::uses_variable(e, name)),
            IRNode::Tuple { elements } => elements.iter().any(|e| Self::uses_variable(e, name)),
            IRNode::Block(nodes) => nodes.iter().any(|n| Self::uses_variable(n, name)),
            _ => false,
        }
    }
}

impl fmt::Display for IRNode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IRNode::IntLiteral(n) => write!(f, "{}", n),
            IRNode::FloatLiteral(n) => write!(f, "{}", n),
            IRNode::StringLiteral(s) => write!(f, "\"{}\"", s),
            IRNode::BoolLiteral(b) => write!(f, "{}", b),
            IRNode::Variable(name) => write!(f, "{}", name),
            IRNode::BinaryOp { op, left, right } => {
                write!(f, "({} {} {})", left, op, right)
            }
            IRNode::UnaryOp { op, operand } => write!(f, "({} {})", op, operand),
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                write!(f, "if ({}) {{ ", condition)?;
                for stmt in then_block {
                    write!(f, "{}; ", stmt)?;
                }
                write!(f, "}}")?;
                if let Some(else_stmts) = else_block {
                    write!(f, " else {{ ")?;
                    for stmt in else_stmts {
                        write!(f, "{}; ", stmt)?;
                    }
                    write!(f, "}}")?;
                }
                Ok(())
            }
            IRNode::FunctionCall { name, args } => {
                write!(f, "{}(", name)?;
                for (i, arg) in args.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", arg)?;
                }
                write!(f, ")")
            }
            IRNode::Array { elements } => {
                write!(f, "[")?;
                for (i, elem) in elements.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", elem)?;
                }
                write!(f, "]")
            }
            IRNode::Index { expr, index } => write!(f, "{}[{}]", expr, index),
            IRNode::Tuple { elements } => {
                write!(f, "(")?;
                for (i, elem) in elements.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", elem)?;
                }
                write!(f, ")")
            }
            IRNode::Assign { name, value } => write!(f, "{} = {}", name, value),
            IRNode::Return(expr) => write!(f, "return {}", expr),
            IRNode::Block(nodes) => {
                write!(f, "{{ ")?;
                for node in nodes {
                    write!(f, "{}; ", node)?;
                }
                write!(f, "}}")
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ir_literal_types() {
        let int_node = IRNode::IntLiteral(42);
        assert!(int_node.returns_value());

        let float_node = IRNode::FloatLiteral(3.14);
        assert!(float_node.returns_value());

        let string_node = IRNode::StringLiteral("hello".to_string());
        assert!(string_node.returns_value());

        let bool_node = IRNode::BoolLiteral(true);
        assert!(bool_node.returns_value());
    }

    #[test]
    fn test_ir_constant_folding_integers() {
        let expr = IRNode::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(IRNode::IntLiteral(2)),
            right: Box::new(IRNode::IntLiteral(3)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(5));
    }

    #[test]
    fn test_ir_constant_folding_floats() {
        let expr = IRNode::BinaryOp {
            op: "Star".to_string(),
            left: Box::new(IRNode::FloatLiteral(2.0)),
            right: Box::new(IRNode::FloatLiteral(3.0)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::FloatLiteral(6.0));
    }

    #[test]
    fn test_ir_if_constant_condition_true() {
        let if_node = IRNode::If {
            condition: Box::new(IRNode::BoolLiteral(true)),
            then_block: vec![IRNode::IntLiteral(42)],
            else_block: Some(vec![IRNode::IntLiteral(0)]),
        };

        let folded = if_node.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(42));
    }

    #[test]
    fn test_ir_if_constant_condition_false() {
        let if_node = IRNode::If {
            condition: Box::new(IRNode::BoolLiteral(false)),
            then_block: vec![IRNode::IntLiteral(42)],
            else_block: Some(vec![IRNode::IntLiteral(0)]),
        };

        let folded = if_node.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(0));
    }

    #[test]
    fn test_ir_unary_op_negation() {
        let expr = IRNode::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(IRNode::IntLiteral(5)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(-5));
    }

    #[test]
    fn test_ir_unary_op_not() {
        let expr = IRNode::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(IRNode::BoolLiteral(true)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::BoolLiteral(false));
    }

    #[test]
    fn test_ir_array_literal() {
        let array = IRNode::Array {
            elements: vec![
                IRNode::IntLiteral(1),
                IRNode::IntLiteral(2),
                IRNode::IntLiteral(3),
            ],
        };

        assert!(array.returns_value());
    }

    #[test]
    fn test_ir_display() {
        let int_node = IRNode::IntLiteral(42);
        assert_eq!(int_node.to_string(), "42");

        let string_node = IRNode::StringLiteral("hello".to_string());
        assert_eq!(string_node.to_string(), "\"hello\"");

        let var_node = IRNode::Variable("x".to_string());
        assert_eq!(var_node.to_string(), "x");
    }
}

