                    _ => IRNode::BinaryOp {
                        op: op.clone(),
                        left: Box::new(left_folded),
                        right: Box::new(right_folded),
                    },
                }
            }
            IRNode::UnaryOp { op, operand } => {
                let operand_folded = operand.fold_constants();
                match (&operand_folded, op.as_str()) {
                    (IRNode::IntLiteral(n), "Minus") => IRNode::IntLiteral(-n),
                    (IRNode::FloatLiteral(n), "Minus") => IRNode::FloatLiteral(-n),
                    (IRNode::BoolLiteral(b), "Not") => IRNode::BoolLiteral(!b),
                    _ => IRNode::UnaryOp {
                        op: op.clone(),
                        operand: Box::new(operand_folded),
                    },
                }
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                let condition_folded = condition.fold_constants();

                // 조건이 상수인 경우 불필요한 분기 제거
                match condition_folded {
                    IRNode::BoolLiteral(true) => {
                        let then_folded: Vec<_> =
                            then_block.iter().map(|n| n.fold_constants()).collect();
                        if then_folded.len() == 1 {
                            then_folded[0].clone()
                        } else {
                            IRNode::Block(then_folded)
                        }
                    }
                    IRNode::BoolLiteral(false) => {
                        if let Some(else_stmts) = else_block {
                            let else_folded: Vec<_> =
                                else_stmts.iter().map(|n| n.fold_constants()).collect();
                            if else_folded.len() == 1 {
                                else_folded[0].clone()
                            } else {
                                IRNode::Block(else_folded)
                            }
                        } else {
                            IRNode::Block(vec![])
                        }
                    }
                    _ => IRNode::If {
                        condition: Box::new(condition_folded),
                        then_block: then_block.iter().map(|n| n.fold_constants()).collect(),
                        else_block: else_block
                            .as_ref()
                            .map(|stmts| stmts.iter().map(|n| n.fold_constants()).collect()),
                    },
                }
            }
            IRNode::Block(nodes) => {
                let folded: Vec<_> = nodes.iter().map(|n| n.fold_constants()).collect();
                IRNode::Block(folded)
            }
            _ => self.clone(),
        }
    }

    /// 불필요한 변수 할당을 제거합니다
    pub fn eliminate_dead_code(&self) -> IRNode {
        match self {
            IRNode::Block(nodes) => {
                let mut live_nodes = Vec::new();

                for (i, node) in nodes.iter().enumerate() {
                    match node {
                        IRNode::Assign { name, value } => {
                            // 다음 사용 위치를 찾습니다
                            let is_used = nodes[i + 1..].iter().any(|n| {
                                Self::uses_variable(n, name)
                            });

                            if is_used {
                                live_nodes.push(node.eliminate_dead_code());
                            }
                            // 그렇지 않으면 제거합니다
                        }
                        _ => {
                            live_nodes.push(node.eliminate_dead_code());
                        }
                    }
                }

                IRNode::Block(live_nodes)
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => IRNode::If {
                condition: Box::new(condition.eliminate_dead_code()),
                then_block: then_block.iter().map(|n| n.eliminate_dead_code()).collect(),
                else_block: else_block
                    .as_ref()
                    .map(|stmts| stmts.iter().map(|n| n.eliminate_dead_code()).collect()),
            },
            _ => self.clone(),
        }
    }

    /// 주어진 변수가 이 노드에서 사용되는지 확인합니다
    fn uses_variable(node: &IRNode, name: &str) -> bool {
        match node {
            IRNode::Variable(n) => n == name,
            IRNode::BinaryOp { left, right, .. } => {
                Self::uses_variable(left, name) || Self::uses_variable(right, name)
            }
            IRNode::UnaryOp { operand, .. } => Self::uses_variable(operand, name),
            IRNode::Index { expr, index } => {
                Self::uses_variable(expr, name) || Self::uses_variable(index, name)
            }
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                Self::uses_variable(condition, name)
                    || then_block.iter().any(|n| Self::uses_variable(n, name))
                    || else_block
                        .as_ref()
                        .map_or(false, |stmts| stmts.iter().any(|n| Self::uses_variable(n, name)))
            }
            IRNode::FunctionCall { args, .. } => {
                args.iter().any(|arg| Self::uses_variable(arg, name))
            }
            IRNode::Array { elements } => elements.iter().any(|e| Self::uses_variable(e, name)),
            IRNode::Tuple { elements } => elements.iter().any(|e| Self::uses_variable(e, name)),
            IRNode::Block(nodes) => nodes.iter().any(|n| Self::uses_variable(n, name)),
            _ => false,
        }
    }
}

impl fmt::Display for IRNode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IRNode::IntLiteral(n) => write!(f, "{}", n),
            IRNode::FloatLiteral(n) => write!(f, "{}", n),
            IRNode::StringLiteral(s) => write!(f, "\"{}\"", s),
            IRNode::BoolLiteral(b) => write!(f, "{}", b),
            IRNode::Variable(name) => write!(f, "{}", name),
            IRNode::BinaryOp { op, left, right } => {
                write!(f, "({} {} {})", left, op, right)
            }
            IRNode::UnaryOp { op, operand } => write!(f, "({} {})", op, operand),
            IRNode::If {
                condition,
                then_block,
                else_block,
            } => {
                write!(f, "if ({}) {{ ", condition)?;
                for stmt in then_block {
                    write!(f, "{}; ", stmt)?;
                }
                write!(f, "}}")?;
                if let Some(else_stmts) = else_block {
                    write!(f, " else {{ ")?;
                    for stmt in else_stmts {
                        write!(f, "{}; ", stmt)?;
                    }
                    write!(f, "}}")?;
                }
                Ok(())
            }
            IRNode::FunctionCall { name, args } => {
                write!(f, "{}(", name)?;
                for (i, arg) in args.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", arg)?;
                }
                write!(f, ")")
            }
            IRNode::Array { elements } => {
                write!(f, "[")?;
                for (i, elem) in elements.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", elem)?;
                }
                write!(f, "]")
            }
            IRNode::Index { expr, index } => write!(f, "{}[{}]", expr, index),
            IRNode::Tuple { elements } => {
                write!(f, "(")?;
                for (i, elem) in elements.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", elem)?;
                }
                write!(f, ")")
            }
            IRNode::Assign { name, value } => write!(f, "{} = {}", name, value),
            IRNode::Return(expr) => write!(f, "return {}", expr),
            IRNode::Block(nodes) => {
                write!(f, "{{ ")?;
                for node in nodes {
                    write!(f, "{}; ", node)?;
                }
                write!(f, "}}")
            }
        }
    }
}

