mod tests {
    use super::*;

    #[test]
    fn test_ir_literal_types() {
        let int_node = IRNode::IntLiteral(42);
        assert!(int_node.returns_value());

        let float_node = IRNode::FloatLiteral(3.14);
        assert!(float_node.returns_value());

        let string_node = IRNode::StringLiteral("hello".to_string());
        assert!(string_node.returns_value());

        let bool_node = IRNode::BoolLiteral(true);
        assert!(bool_node.returns_value());
    }

    #[test]
    fn test_ir_constant_folding_integers() {
        let expr = IRNode::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(IRNode::IntLiteral(2)),
            right: Box::new(IRNode::IntLiteral(3)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(5));
    }

    #[test]
    fn test_ir_constant_folding_floats() {
        let expr = IRNode::BinaryOp {
            op: "Star".to_string(),
            left: Box::new(IRNode::FloatLiteral(2.0)),
            right: Box::new(IRNode::FloatLiteral(3.0)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::FloatLiteral(6.0));
    }

    #[test]
    fn test_ir_if_constant_condition_true() {
        let if_node = IRNode::If {
            condition: Box::new(IRNode::BoolLiteral(true)),
            then_block: vec![IRNode::IntLiteral(42)],
            else_block: Some(vec![IRNode::IntLiteral(0)]),
        };

        let folded = if_node.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(42));
    }

    #[test]
    fn test_ir_if_constant_condition_false() {
        let if_node = IRNode::If {
            condition: Box::new(IRNode::BoolLiteral(false)),
            then_block: vec![IRNode::IntLiteral(42)],
            else_block: Some(vec![IRNode::IntLiteral(0)]),
        };

        let folded = if_node.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(0));
    }

    #[test]
    fn test_ir_unary_op_negation() {
        let expr = IRNode::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(IRNode::IntLiteral(5)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::IntLiteral(-5));
    }

    #[test]
    fn test_ir_unary_op_not() {
        let expr = IRNode::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(IRNode::BoolLiteral(true)),
        };

        let folded = expr.fold_constants();
        assert_eq!(folded, IRNode::BoolLiteral(false));
    }

    #[test]
    fn test_ir_array_literal() {
        let array = IRNode::Array {
            elements: vec![
                IRNode::IntLiteral(1),
                IRNode::IntLiteral(2),
                IRNode::IntLiteral(3),
            ],
        };

        assert!(array.returns_value());
    }

    #[test]
    fn test_ir_display() {
        let int_node = IRNode::IntLiteral(42);
        assert_eq!(int_node.to_string(), "42");

        let string_node = IRNode::StringLiteral("hello".to_string());
        assert_eq!(string_node.to_string(), "\"hello\"");

        let var_node = IRNode::Variable("x".to_string());
        assert_eq!(var_node.to_string(), "x");
    }
}

