    /// 새 컴파일러 생성
    pub fn new() -> Self {
        Compiler {
            lexer: Lexer::new(""),
            parser: Parser::new(Vec::new()),
            type_checker: TypeChecker::new(),
            codegen: CodeGenerator::new(),
            runtime: Runtime::new(),
        }
    }

    /// 소스 코드 컴파일 및 실행
    pub fn compile_and_run(&mut self, source: &str) -> Result<Value, CompileError> {
        // Step 1: Lexer (소스 → 토큰)
        let mut lexer = Lexer::new(source);
        let tokens = lexer
            .tokenize()
            .map_err(|e| CompileError::LexerError(e.to_string()))?;

        // Step 2: Parser (토큰 → AST)
        let parser = Parser::new(tokens);
        let ast = parser
            .parse()
            .map_err(|e| CompileError::ParserError(e.to_string()))?;

        // Step 3: Type Checker (AST → Typed AST)
        let type_checker = TypeChecker::new();
        let typed_ast = type_checker
            .check(&ast)
            .map_err(|e| CompileError::TypeError(e.to_string()))?;

        // Step 4: Code Generator (Typed AST → IR)
        let codegen = CodeGenerator::new();
        let ir = codegen
            .ast_to_ir(&typed_ast)
            .map_err(|e| CompileError::CodegenError(e.to_string()))?;

        // Step 5: Runtime (IR → 실행)
        let result = self.runtime.execute(&ir)?;

        Ok(result)
    }

