// 컴파일러 통합 (Compiler Integration)
// Phase 5 Stage 3: 완전한 컴파일 파이프라인

use crate::lexer::Lexer;
use crate::parser::Parser;
use crate::type_checker::TypeChecker;
use crate::codegen::CodeGenerator;
use crate::runtime::{Runtime, RuntimeError};
use crate::value::Value;

/// 컴파일 에러
#[derive(Debug, Clone)]
pub enum CompileError {
    LexerError(String),
    ParserError(String),
    TypeError(String),
    CodegenError(String),
    RuntimeError(String),
}

impl std::fmt::Display for CompileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CompileError::LexerError(e) => write!(f, "Lexer error: {}", e),
            CompileError::ParserError(e) => write!(f, "Parser error: {}", e),
            CompileError::TypeError(e) => write!(f, "Type error: {}", e),
            CompileError::CodegenError(e) => write!(f, "Code generation error: {}", e),
            CompileError::RuntimeError(e) => write!(f, "Runtime error: {}", e),
        }
    }
}

impl std::error::Error for CompileError {}

impl From<RuntimeError> for CompileError {
    fn from(err: RuntimeError) -> Self {
        CompileError::RuntimeError(err.to_string())
    }
}

